from pathlib import Path
import re
p=Path('/home/ubuntu/work/index.html')
s=p.read_text()
# Keep the global ayah number so a verse button can request only that verse.
s=s.replace("v:(s.ayahs||[]).map(v=>[String(v.text||'').replace(/^\\uFEFF/,'') ,String(v.text||'').replace(/^\\uFEFF/,'') ,''])", "v:(s.ayahs||[]).map(v=>[String(v.text||'').replace(/^\\uFEFF/,'') ,String(v.text||'').replace(/^\\uFEFF/,'') ,'',v.global||v.number])")
# Add exact ayah URL selection based on the chosen reciter, with a reliable Alafasy fallback.
s=s.replace("function recitationUrl(i){const r=selectedReciter(),m=r&&r.moshaf&&r.moshaf[0];return m?`${m.server}${String(i+1).padStart(3,'0')}.mp3`:''}", """function recitationUrl(i){const r=selectedReciter(),m=r&&r.moshaf&&r.moshaf[0];return m?`${m.server}${String(i+1).padStart(3,'0')}.mp3`:''}
function ayahEdition(){const n=normalizeSearch((selectedReciter()||{}).name||'');if(n.includes('مشاري')||n.includes('afasy'))return 'ar.alafasy';if(n.includes('ماهر')||n.includes('muaiqly'))return 'ar.mahermuaiqly';if(n.includes('حصري')||n.includes('husary'))return 'ar.husary';if(n.includes('منشاوي')||n.includes('minshawi'))return 'ar.minshawi';return 'ar.alafasy'}
function ayahUrl(si,ai){const g=SUR[si]?.v?.[ai]?.[3];return g?`https://cdn.islamic.network/quran/audio/128/${ayahEdition()}/${g}.mp3`:''}""")
# Replace playback function with optional exact ayah mode.
s=s.replace("function playRecitation(i){const url=recitationUrl(i);", "function playRecitation(i,exactAyah=false){const url=exactAyah?ayahUrl(S.surah,i):recitationUrl(i);")
# Use exact ayah when clicking verse playback.
s=s.replace("A('[data-p]',e=>{const i=+e.dataset.p;S.all=false;S.vp=S.vp===i?-1:i;if(S.vp>=0)playRecitation(S.surah);else stopAudio();render()});", "A('[data-p]',e=>{const i=+e.dataset.p;S.all=false;S.vp=S.vp===i?-1:i;if(S.vp>=0)playRecitation(i,true);else stopAudio();render()});")
# Add more snippet cards and content.
s=s.replace("const SNIP=[['أحاديث','book'],['أذكار','lay'],['الموسوعة التاريخية','book'],['علامات الساعة','hist'],['الرقية الشرعية','per'],['أسماء الله الحسنى','book'],['فضائل العبادات','gift'],['أدعية من القرآن','star'],['نساء عظيمة','per'],['العشرة المبشرون بالجنة','star'],['إعجاز القرآن','book'],['آية وعبرة','moon'],['تحدي الأسئلة','cc']];", "const SNIP=[['أحاديث','book'],['أذكار','lay'],['الموسوعة التاريخية','book'],['علامات الساعة','hist'],['الرقية الشرعية','per'],['أسماء الله الحسنى','book'],['فضائل العبادات','gift'],['أدعية من القرآن','star'],['نساء عظيمة','per'],['العشرة المبشرون بالجنة','star'],['إعجاز القرآن','book'],['آية وعبرة','moon'],['تحدي الأسئلة','cc'],['فضائل القرآن','book'],['السيرة النبوية','hist'],['أدعية الصباح والمساء','star'],['الصلاة على النبي','gift'],['قصص الأنبياء','per'],['محاسن الأخلاق','cc']];")
s=s.replace("let PR=[['الفجر',4,50]", "DET[13]=[['فضل تلاوة القرآن','القرآن نور وهدى وشفاعة لصاحبه'],['خيركم من تعلم القرآن وعلمه','رواه البخاري']];DET[14]=[['مولد النبي ﷺ','محطات من السيرة النبوية العطرة'],['الهجرة إلى المدينة','درس في الصبر والتوكل']];DET[15]=[['أصبحنا وأصبح الملك لله','ذكر الصباح'],['أمسينا وأمسى الملك لله','ذكر المساء']];DET[16]=[['إن الله وملائكته يصلون على النبي','الأحزاب ٥٦'],['من صلى علي واحدة صلى الله عليه بها عشرًا','رواه مسلم']];DET[17]=[['قصة نوح عليه السلام','دعوة وصبر وثبات'],['قصة يوسف عليه السلام','العفو عند المقدرة']];DET[18]=[['الصدق أمانة','من محاسن الأخلاق'],['الرحمة بالخلق','خلق يحبه الله']];\nlet PR=[['الفجر',4,50]")
# Replace the old hero homepage with a stacked dark dashboard inspired by the supplied reference.
new_home="""home(){const pr=prayers(),dt=dates(),r=selectedReciter()||{},photo=r.image_local||'/assets/logo.png',ai=S.ap==null?0:S.ap,as=SUR[ai]||SUR[0]||{};S.np=pr.n;
 return `<div class=\"home-dashboard\"><div class=\"home-heading\"><div><small>${S.lang==='en'?'Muslim encyclopedia':S.lang==='fr'?'Encyclopédie musulmane':S.lang==='ur'?'اسلامی انسائیکلوپیڈیا':'موسوعة المسلم'}</small><b>${S.lang==='en'?'Your daily companion':S.lang==='fr'?'Votre compagnon quotidien':S.lang==='ur'?'آپ کا روزانہ ساتھی':'رفيقك اليومي'}</b></div><button class=\"ib\" id=\"st\">${I('gear')}</button></div>
 <section class=\"home-prayer-card\"><div class=\"home-card-title\"><span>${I('cc')} ${S.lang==='en'?'Prayer times':S.lang==='fr'?'Horaires de prière':S.lang==='ur'?'نماز کے اوقات':'مواقيت الصلاة'}</span><button id=\"loc\">${I('pin')}</button></div><div class=\"next-prayer\"><div><small>${S.lang==='en'?'Next prayer':S.lang==='fr'?'Prochaine prière':S.lang==='ur'?'اگلی نماز':'الصلاة القادمة'}</small><b>${pr.n}</b></div><strong>${pr.cd}</strong></div><div class=\"prayer-meta\"><span>${I('pin')} ${S.geoName|| (S.lang==='en'?'Your location':'موقعك الحالي')}</span><span>${I('hist')} ${dt[0]}</span></div><div class=\"prayer-strip\">${PR.map((p,i)=>`<span class=\"${i===pr.i?'on':''}\"><small>${PL(p[0])}</small><b>${ar(p2(p[1]>12?p[1]-12:p[1]))}:${ar(p2(p[2]))}</b></span>`).join('')}</div></section>
 <section class=\"home-audio-card\"><div class=\"home-audio-top\"><button class=\"mini-action\">${I('exp')}</button><div><b>${S.lang==='en'?'Featured recitation':S.lang==='fr'?'Récitation en vedette':S.lang==='ur'?'منتخب تلاوت':'تلاوة مميزة'}</b><small>${r.name||'مشاري العفاسي'} · ${SN(as)}</small></div><img src=\"${photo}\" alt=\"${r.name||'القارئ'}\" onerror=\"this.src='/assets/logo.png'\"></div><div class=\"home-audio-controls\"><button data-audio-skip=\"prev\">${I('skipPrev')}</button><button class=\"home-play\" data-mainplay=\"1\">${I(S.ap!==null&&!audioEl.paused?'pause':'play')}</button><button data-audio-skip=\"next\">${I('skipNext')}</button></div><div class=\"home-progress\"><span>${fmt(audioEl.currentTime||0)}</span><input id=\"homeSeek\" type=\"range\" min=\"0\" max=\"${audioEl.duration||1}\" value=\"${audioEl.currentTime||0}\"><span>${fmt(audioEl.duration||0)}</span></div></section>
 <section class=\"home-content-card\"><div class=\"content-icon\">${I('star')}</div><div><b>${T('daily')}</b><p>${(DAILY_COPY[S.lang]||DAILY_COPY.ar)[0]}</p><small>${(DAILY_COPY[S.lang]||DAILY_COPY.ar)[1]}</small></div></section><section class=\"home-content-card\"><div class=\"content-icon\">${I('book')}</div><div><b>${T('dailyVerse')}</b><p>﴿فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا﴾</p><small>${T('about')}</small></div></section>
 <div class=\"home-quick-grid\"><button data-go=\"quran\">${I('book')}<span>${L('quran')}</span></button><button data-go=\"aud\">${I('head')}<span>${L('aud')}</span></button><button data-go=\"vid\">${I('film')}<span>${L('vid')}</span></button><button data-go=\"quiz\"><span class=\"q\">؟</span><span>${T('quiz')}</span></button></div><div class=\"home-section-title\"><b>${S.lang==='en'?'More highlights':S.lang==='fr'?'Plus de contenus':S.lang==='ur'?'مزید منتخب مواد':'مقتطفات أكثر'}</b><button data-go=\"snip\">${I('back')}</button></div><div class=\"home-highlights\">${SNIP.slice(0,8).map(([l,ic],i)=>`<button data-n=\"${i}\">${I(ic)}<span>${SL(i,l)}</span></button>`).join('')}</div></div>`},
"""
s=re.sub(r"home\(\)\{[\s\S]*?\},\n\s*vid\(",new_home+" vid(",s,count=1)
# add styling before closing style tag
css=""".home-dashboard{padding:0 0 18px}.home-heading{display:flex;align-items:center;justify-content:space-between;padding:2px 4px 12px}.home-heading small,.home-heading b{display:block}.home-heading small{font-size:10px;color:#aaa}.home-heading b{font-size:17px;margin-top:3px}.home-prayer-card,.home-audio-card,.home-content-card{background:#050505;border-radius:20px;padding:14px;margin-bottom:9px;box-shadow:0 8px 25px rgba(0,0,0,.22)}.home-card-title,.home-audio-top,.home-section-title{display:flex;align-items:center;justify-content:space-between}.home-card-title{font-size:13px;color:#ddd}.home-card-title svg{width:18px;height:18px}.next-prayer{display:flex;align-items:center;justify-content:space-between;background:#101010;border-radius:15px;padding:14px 12px;margin-top:10px}.next-prayer small,.next-prayer b{display:block}.next-prayer small{font-size:9px;color:#999}.next-prayer b{font-size:20px;margin-top:4px}.next-prayer strong{font:700 24px system-ui;color:#eee;direction:ltr}.prayer-meta{display:flex;justify-content:space-between;gap:5px;color:#929292;font-size:8px;border-bottom:1px solid #222;padding:10px 0}.prayer-meta span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.prayer-strip{display:flex;gap:3px;padding-top:8px}.prayer-strip span{flex:1;text-align:center;padding:6px 2px;border-radius:9px}.prayer-strip span.on{background:#0b86c9;color:#fff}.prayer-strip small,.prayer-strip b{display:block;font-size:8px}.home-audio-top{direction:rtl;gap:8px}.home-audio-top>div{flex:1}.home-audio-top b,.home-audio-top small{display:block}.home-audio-top b{font-size:11px}.home-audio-top small{font-size:8px;color:#999;margin-top:4px}.home-audio-top img{width:48px;height:48px;object-fit:cover;border-radius:50%;border:1px solid #444}.mini-action{align-self:flex-start}.mini-action svg{width:16px;height:16px}.home-audio-controls{display:flex;justify-content:center;align-items:center;gap:24px;direction:ltr;margin:12px 0 7px}.home-audio-controls button{width:24px;height:24px}.home-audio-controls svg{width:20px;height:20px}.home-audio-controls .home-play{width:38px;height:38px;background:#0b86c9;border-radius:50%;display:flex;align-items:center;justify-content:center}.home-audio-controls .home-play svg{width:24px;height:24px}.home-progress{display:flex;gap:6px;align-items:center;font:8px system-ui;direction:ltr;color:#aaa}.home-progress input{accent-color:#0b86c9}.home-content-card{display:flex;align-items:center;gap:12px;direction:rtl}.home-content-card .content-icon{width:44px;height:44px;border-radius:14px;border:1px solid #222;background:#0d0d0d;display:flex;align-items:center;justify-content:center;flex:none}.content-icon svg{width:25px;height:25px;fill:#f6b93b}.home-content-card>div:last-child{flex:1}.home-content-card b{font-size:12px}.home-content-card p{font-family:Amiri,serif;font-size:13px;line-height:1.6;margin-top:4px}.home-content-card small{color:#888;font-size:8px}.home-quick-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-bottom:12px}.home-quick-grid button{background:#050505;border-radius:15px;padding:10px 4px;display:flex;align-items:center;flex-direction:column;gap:6px;font-size:9px}.home-quick-grid svg{width:22px;height:22px}.home-quick-grid .q{font-size:22px;line-height:22px}.home-section-title{font-size:13px;padding:4px 3px 9px}.home-section-title button{color:#4fb3ec;font-size:10px}.home-section-title button svg{width:17px;height:17px}.home-highlights{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.home-highlights button{background:#050505;border-radius:14px;min-height:64px;padding:8px 3px;display:flex;align-items:center;flex-direction:column;justify-content:center;gap:5px;font-size:8px;text-align:center}.home-highlights svg{width:22px;height:22px;fill:#4fb3ec}.home-highlights span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
"""
